+1|// Stock market visualization: sector-clustered bubble chart + linked data table.
+2|// Uses D3 v6. Deterministic layout (fixed simulation seed via sorted inputs and
+3|// fixed number of ticks; no randomness, no transitions).
+4|
+5|const CHART_WIDTH = 860;
+6|const CHART_HEIGHT = 640;
+7|const MARGIN = { top: 20, right: 20, bottom: 20, left: 20 };
+8|
+9|const SECTOR_ORDER = [
+10|    "Information Technology",
+11|    "Financial",
+12|    "Industry",
+13|    "Energy",
+14|    "ETF",
+15|];
+16|
+17|const SECTOR_COLORS = {
+18|    "Information Technology": "#2563eb",
+19|    "Financial": "#059669",
+20|    "Industry": "#d97706",
+21|    "Energy": "#dc2626",
+22|    "ETF": "#7c3aed",
+23|};
+24|
+25|// Fixed uniform bubble radius for ETFs (no market cap available).
+26|const ETF_RADIUS = 22;
+27|
+28|function formatMarketCap(value) {
+29|    if (value == null || isNaN(value) || value === 0) return "—";
+30|    const abs = Math.abs(value);
+31|    if (abs >= 1e12) return (value / 1e12).toFixed(2) + "T";
+32|    if (abs >= 1e9) return (value / 1e9).toFixed(2) + "B";
+33|    if (abs >= 1e6) return (value / 1e6).toFixed(2) + "M";
+34|    if (abs >= 1e3) return (value / 1e3).toFixed(2) + "K";
+35|    return value.toFixed(0);
+36|}
+37|
+38|function parseRow(d) {
+39|    const mc = d.marketCap && d.marketCap.trim() !== "" ? +d.marketCap : null;
+40|    return {
+41|        ticker: d.ticker,
+42|        sector: d.sector,
+43|        name: d["full name"],
+44|        marketCap: Number.isFinite(mc) ? mc : null,
+45|        country: d.country || "",
+46|        website: d.website || "",
+47|    };
+48|}
+49|
+50|d3.csv("data/stock-descriptions.csv", parseRow).then((rawData) => {
+51|    // Deterministic ordering: by sector then by descending market cap then ticker.
+52|    const data = rawData.slice().sort((a, b) => {
+53|        const sa = SECTOR_ORDER.indexOf(a.sector);
+54|        const sb = SECTOR_ORDER.indexOf(b.sector);
+55|        if (sa !== sb) return sa - sb;
+56|        const ma = a.marketCap || 0;
+57|        const mb = b.marketCap || 0;
+58|        if (mb !== ma) return mb - ma;
+59|        return d3.ascending(a.ticker, b.ticker);
+60|    });
+61|
+62|    buildBubbleChart(data);
+63|    buildTable(data);
+64|});
+65|
+66|function buildBubbleChart(data) {
+67|    const innerW = CHART_WIDTH - MARGIN.left - MARGIN.right;
+68|    const innerH = CHART_HEIGHT - MARGIN.top - MARGIN.bottom;
+69|
+70|    // Radius scale for companies (has market cap). ETFs use fixed radius.
+71|    const nonEtfCaps = data
+72|        .filter((d) => d.sector !== "ETF" && d.marketCap)
+73|        .map((d) => d.marketCap);
+74|    const radius = d3
+75|        .scaleSqrt()
+76|        .domain([d3.min(nonEtfCaps), d3.max(nonEtfCaps)])
+77|        .range([14, 55]);
+78|
+79|    data.forEach((d) => {
+80|        d.r = d.sector === "ETF" ? ETF_RADIUS : radius(d.marketCap);
+81|    });
+82|
+83|    // Cluster centers arranged around the middle of the plot area so that
+84|    // all sectors stay reasonably centered rather than being pushed to edges.
+85|    const sectors = SECTOR_ORDER.filter((s) =>
+86|        data.some((d) => d.sector === s)
+87|    );
+88|    const clusterCenters = computeClusterCenters(sectors, innerW, innerH);
+89|
+90|    // Deterministic initial positions: place each bubble at its cluster center
+91|    // with a tiny sector-index offset so the force simulation converges the
+92|    // same way on every run.
+93|    data.forEach((d, i) => {
+94|        const c = clusterCenters[d.sector];
+95|        d.x = c.x + ((i % 7) - 3);
+96|        d.y = c.y + ((i % 5) - 2);
+97|    });
+98|
+99|    const svg = d3
+100|        .select("#bubble-chart")
+101|        .append("svg")
+102|        .attr("viewBox", `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
+103|        .attr("preserveAspectRatio", "xMidYMid meet");
+104|
+105|    const g = svg
+106|        .append("g")
+107|        .attr("transform", `translate(${MARGIN.left},${MARGIN.top})`);
+108|
+109|    // Force simulation: cluster by sector via forceX/forceY toward each
+110|    // sector's cluster center, plus forceCollide to prevent overlap.
+111|    const simulation = d3
+112|        .forceSimulation(data)
+113|        .force(
+114|            "x",
+115|            d3.forceX((d) => clusterCenters[d.sector].x).strength(0.18)
+116|        )
+117|        .force(
+118|            "y",
+119|            d3.forceY((d) => clusterCenters[d.sector].y).strength(0.18)
+120|        )
+121|        .force(
+122|            "collide",
+123|            d3.forceCollide((d) => d.r + 1.5).iterations(3)
+124|        )
+125|        .force("center", d3.forceCenter(innerW / 2, innerH / 2).strength(0.02))
+126|        .stop();
+127|
+128|    // Run a fixed number of ticks for a deterministic layout.
+129|    const TICKS = 400;
+130|    for (let i = 0; i < TICKS; i++) simulation.tick();
+131|
+132|    // Clamp inside plot area to avoid stragglers.
+133|    data.forEach((d) => {
+134|        d.x = Math.max(d.r, Math.min(innerW - d.r, d.x));
+135|        d.y = Math.max(d.r, Math.min(innerH - d.r, d.y));
+136|    });
+137|
+138|    const nodeGroups = g
+139|        .selectAll("g.node")
+140|        .data(data, (d) => d.ticker)
+141|        .enter()
+142|        .append("g")
+143|        .attr("class", "node")
+144|        .attr("data-ticker", (d) => d.ticker)
+145|        .attr("transform", (d) => `translate(${d.x},${d.y})`);
+146|
+147|    nodeGroups
+148|        .append("circle")
+149|        .attr("class", "bubble")
+150|        .attr("r", (d) => d.r)
+151|        .attr("fill", (d) => SECTOR_COLORS[d.sector] || "#64748b")
+152|        .attr("fill-opacity", 0.85);
+153|
+154|    nodeGroups
+155|        .append("text")
+156|        .attr("class", "bubble-label")
+157|        .text((d) => d.ticker)
+158|        .style("font-size", (d) => {
+159|            // Scale label size within a small range so long tickers still fit.
+160|            const size = Math.max(9, Math.min(14, d.r * 0.45));
+161|            return `${size}px`;
+162|        });
+163|
+164|    // Interactivity: tooltip + click selection wired to the table.
+165|    const tooltip = d3.select("#tooltip");
+166|
+167|    nodeGroups
+168|        .on("mouseover", function (event, d) {
+169|            if (d.sector === "ETF") return; // No tooltip for ETFs.
+170|            tooltip
+171|                .classed("visible", true)
+172|                .html(
+173|                    `<div class="tt-ticker">${d.ticker}</div>` +
+174|                        `<div class="tt-name">${d.name}</div>` +
+175|                        `<div class="tt-sector">${d.sector}</div>`
+176|                )
+177|                .style("left", event.pageX + 12 + "px")
+178|                .style("top", event.pageY - 12 + "px");
+179|        })
+180|        .on("mousemove", function (event, d) {
+181|            if (d.sector === "ETF") return;
+182|            tooltip
+183|                .style("left", event.pageX + 12 + "px")
+184|                .style("top", event.pageY - 12 + "px");
+185|        })
+186|        .on("mouseout", function () {
+187|            tooltip.classed("visible", false);
+188|        })
+189|        .on("click", function (event, d) {
+190|            selectTicker(d.ticker);
+191|        });
+192|
+193|    buildLegend(sectors);
+194|}
+195|
+196|function computeClusterCenters(sectors, innerW, innerH) {
+197|    // Place sector centers on a compact ring around the middle so that all
+198|    // clusters sit near the visual center of the chart.
+199|    const centers = {};
+200|    const cx = innerW / 2;
+201|    const cy = innerH / 2;
+202|    const radius = Math.min(innerW, innerH) * 0.22;
+203|    const n = sectors.length;
+204|
+205|    sectors.forEach((s, i) => {
+206|        // Start at top and go clockwise.
+207|        const angle = -Math.PI / 2 + (i * 2 * Math.PI) / n;
+208|        centers[s] = {
+209|            x: cx + radius * Math.cos(angle),
+210|            y: cy + radius * Math.sin(angle),
+211|        };
+212|    });
+213|
+214|    return centers;
+215|}
+216|
+217|function buildLegend(sectors) {
+218|    const legend = d3.select("#legend");
+219|    legend
+220|        .selectAll("div.legend-item")
+221|        .data(sectors)
+222|        .enter()
+223|        .append("div")
+224|        .attr("class", "legend-item")
+225|        .html(
+226|            (s) =>
+227|                `<span class="legend-swatch" style="background:${SECTOR_COLORS[s]}"></span>` +
+228|                `<span>${s}</span>`
+229|        );
+230|}
+231|
+232|function buildTable(data) {
+233|    const tbody = d3.select("#stock-table tbody");
+234|
+235|    const rows = tbody
+236|        .selectAll("tr")
+237|        .data(data, (d) => d.ticker)
+238|        .enter()
+239|        .append("tr")
+240|        .attr("data-ticker", (d) => d.ticker)
+241|        .on("click", function (event, d) {
+242|            selectTicker(d.ticker);
+243|        });
+244|
+245|    rows.append("td").attr("class", "ticker-cell").text((d) => d.ticker);
+246|    rows.append("td").text((d) => d.name);
+247|    rows.append("td").text((d) => d.sector);
+248|    rows.append("td")
+249|        .attr("class", "market-cap-cell")
+250|        .text((d) => formatMarketCap(d.marketCap));
+251|}
+252|
+253|function selectTicker(ticker) {
+254|    // Toggle selected class on both the bubble and the matching table row.
+255|    const alreadySelected = d3
+256|        .select(`.node[data-ticker="${ticker}"] circle`)
+257|        .classed("selected");
+258|
+259|    d3.selectAll(".bubble").classed("selected", false);
+260|    d3.selectAll("#stock-table tbody tr").classed("selected", false);
+261|
+262|    if (!alreadySelected) {
+263|        d3.select(`.node[data-ticker="${ticker}"] circle`).classed(
+264|            "selected",
+265|            true
+266|        );
+267|        const row = d3.select(`#stock-table tbody tr[data-ticker="${ticker}"]`);
+268|        row.classed("selected", true);
+269|        // Scroll the selected row into view within the scrollable table.
+270|        const rowNode = row.node();
+271|        if (rowNode && rowNode.scrollIntoView) {
+272|            rowNode.scrollIntoView({ block: "nearest" });
+273|        }
+274|    }
+275|}
+276|
